def first_odd(nums):
    """
    Identifies the initial odd integer within a provided list of integers.

    :param nums: A list of integers
    :return: The first odd integer found in the list or None if no odd integer exists
    """
    for num in nums:
        if num % 2 != 0:
            return num
    return None

def freq_count(input_data):
    """
    Calculates the frequency of each unique element in the given data structure.

    :param input_data: A list, tuple, set, or any iterable containing hashable elements.
    :return: A dictionary with elements as keys and their corresponding frequencies as values.
    """
    frequency_map = {}
    for element in input_data:
        if element in frequency_map:
            frequency_map[element] += 1
        else:
            frequency_map[element] = 1
    return frequency_map

